import pandas as pd
import re
from datetime import datetime

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw_payments = inputs["raw_payments"].copy()

    # Initialize reject tracking
    rejects = []
    valid_rows = []

    for idx, row in raw_payments.iterrows():
        row_num = row["row_num"]
        payment_id = row["payment_id"]
        account_id = row["account_id"]
        amount_txt = row["amount_txt"]
        currency = row["currency"]
        pay_date_txt = row["pay_date_txt"]

        reject_reason = None

        # R1: MISSING_ID
        if reject_reason is None:
            if pd.isna(payment_id) or (isinstance(payment_id, str) and payment_id.strip() == ""):
                reject_reason = "MISSING_ID"

        # R2: BAD_AMOUNT
        if reject_reason is None:
            if pd.isna(amount_txt):
                reject_reason = "BAD_AMOUNT"
            else:
                amount_trimmed = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
                # Legacy number pattern: optional +/-, one or more digits, optional .DD
                if not re.match(r'^[+-]?\d+(\.\d{1,2})?$', amount_trimmed):
                    reject_reason = "BAD_AMOUNT"

        # R3: NON_POSITIVE
        if reject_reason is None:
            try:
                amount_trimmed = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
                parsed_amount = float(amount_trimmed)
                if parsed_amount <= 0:
                    reject_reason = "NON_POSITIVE"
            except (ValueError, AttributeError):
                reject_reason = "BAD_AMOUNT"

        # R4: BAD_CURRENCY
        if reject_reason is None:
            if pd.isna(currency):
                reject_reason = "BAD_CURRENCY"
            else:
                currency_upper = currency.strip().upper() if isinstance(currency, str) else str(currency).upper()
                if currency_upper not in ["USD", "EUR", "GBP"]:
                    reject_reason = "BAD_CURRENCY"

        # R5: BAD_DATE
        if reject_reason is None:
            if pd.isna(pay_date_txt):
                reject_reason = "BAD_DATE"
            else:
                pay_date_trimmed = pay_date_txt.strip() if isinstance(pay_date_txt, str) else str(pay_date_txt)
                # Check exact format YYYY-MM-DD
                if not re.match(r'^\d{4}-\d{2}-\d{2}$', pay_date_trimmed):
                    reject_reason = "BAD_DATE"
                else:
                    try:
                        parsed_date = datetime.strptime(pay_date_trimmed, "%Y-%m-%d")
                    except ValueError:
                        reject_reason = "BAD_DATE"

        if reject_reason is not None:
            rejects.append({"row_num": row_num, "reject_reason": reject_reason})
        else:
            # Row passed R1-R5, store for duplicate check
            amount_trimmed = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
            parsed_amount = float(amount_trimmed)
            currency_upper = currency.strip().upper() if isinstance(currency, str) else str(currency).upper()
            pay_date_trimmed = pay_date_txt.strip() if isinstance(pay_date_txt, str) else str(pay_date_txt)
            parsed_date = datetime.strptime(pay_date_trimmed, "%Y-%m-%d").date()
            payment_id_trimmed = payment_id.strip() if isinstance(payment_id, str) else str(payment_id)

            valid_rows.append({
                "row_num": row_num,
                "payment_id": payment_id_trimmed,
                "account_id": account_id,
                "amount": parsed_amount,
                "currency": currency_upper,
                "pay_date": parsed_date
            })

    # R6: DUPLICATE - among valid rows, keep only first occurrence by payment_id
    valid_df = pd.DataFrame(valid_rows)

    if len(valid_df) > 0:
        # Group by payment_id and keep only the row with minimum row_num
        duplicates_mask = valid_df.duplicated(subset=["payment_id"], keep="first")
        duplicate_row_nums = valid_df[duplicates_mask]["row_num"].tolist()

        # Add duplicates to rejects
        for row_num in duplicate_row_nums:
            rejects.append({"row_num": row_num, "reject_reason": "DUPLICATE"})

        # Filter valid_df to keep only first occurrences
        valid_df = valid_df[~duplicates_mask]

        # Reorder columns
        valid_df = valid_df[["payment_id", "account_id", "amount", "currency", "pay_date"]]
    else:
        valid_df = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])

    # Create rejects dataframe
    if rejects:
        rejects_df = pd.DataFrame(rejects)
        rejects_df = rejects_df.sort_values("row_num").reset_index(drop=True)
    else:
        rejects_df = pd.DataFrame(columns=["row_num", "reject_reason"])

    return {
        "valid_payments": valid_df.reset_index(drop=True),
        "payment_rejects": rejects_df
    }
